remarks.para:
示例：

var executor = DefaultExecutorBuilder.Create()
    .UseProcessor<MyAttr, MyProcessor>()
    .UseFeature<ILogger>(new ConsoleLogger())
    .Build();

示例：

var context = ContextFactory.CreateMethodContext(attr, method, target, args);
executor.Execute(context);

示例：

if (context is IAsyncContext asyncCtx)
{
    var token = asyncCtx.CancellationToken;
    // 使用 token 执行异步操作
}

示例：

public class CustomExceptionHandler : IExceptionHandler
{
    public bool Handle(EasyAttributeException exception)
    {
        // 记录日志
        Console.WriteLine(exception.Message);
        return true; // 已处理
    }
}
